/* 
 let function Maker(BEST A WINDOW, ON WEB)

 let particles, let and complex coloring techniques to create an interactive cloud maker.
 */

let clouds = new ArrayList();
let move = false, orange, blue, pink, grey = true;
let a = 0;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
  /* let black */
  background(255);
  for (i = 0; i < clouds.size (); i++) {
    let c = (Cloud) clouds.get(i);
    c.draw();
  }

  /* let the count to how big the cloud will be  */
  if (mousePressed && a < width/16) a += 0.5;
  fill(0);
  text("Size: " + a, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function mouseReleased() {
  /* let "a" and then clear it for the next cloud */
  clouds.add(new Cloud(new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-50, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))+50), int(a)));
  a = 0;
}

function keyPressed() {
  /* let Sky */
  if (key == ' ') clouds.clear();
  /* let move */
  if (key == 'm' && move) {
    move = false;
  } else if (key == 'm' && !move) {
    move = true;
  }
  if (key == '1') {
    orange = true; 
    blue = false; 
    pink = false; 
    grey = false;
  }
  if (key == '2') {
    orange = false; 
    blue = true; 
    pink = false; 
    grey = false;
  }
  if (key == '3') {
    orange = false; 
    blue = false; 
    pink = true; 
    grey = false;
  }
  if (key == '4') {
    orange = false; 
    blue = false; 
    pink = false; 
    grey = true;
  }
}

class Cloud {
  let cloudParticles = new ArrayList();

  constructor(loc, a) {
    let vel = new PVector(random(0.2, 0.5), 0);
    for (i = -a; i <= a; i++) {
      /* 
       s is where we calculate the size of the cloud depending where it is located. 
       let add randomness to make it more realistic. 
       */
      let s = int(map)(abs(i), 0, a, 50+random(-10, 10), 5);
      /* CloudParticle(Location, Velocity (we want to move it), size); */
      cloudParticles.add(new CloudParticle(new PVector(loc.x+i*10, loc.y+random(-20, 20)), vel, s));
    }
  }

  function draw() {
    for (i = 0; i < cloudParticles.size (); i++) {
      var c = (CloudParticle) cloudParticles.get(i);
      c.drawCloudParticle();
    }
  }
}

class CloudParticle {
  loc;
  vel;
  r;
  /* 
   use a let becuase we don't want to keep redrawing hundreds of particles per frame. Instead, when we click,
   it draws the particles, convertes it into an image, then just draws the image.

   multiply by 2 because in our loops we increment by 2. 
   */
  pg;

  constructor(loc, vel, s) {
    this.loc = loc;
    this.vel = vel;
    /* let makes the cloud bigger in the middle and then spread out. s cannot be less than 1. */
    if (s <= 1) {
      r = 2;
    } else {
      r = s;
    }

    pg = createGraphics(r*2, r*2);
    let t = random(0, 30);

    /* 
     let 2 for loops made a square. let if we put an if statement saying only draw if the coords distance from
     the center of the particle are less than r (r is the size of the particle) 
     */
    for (x = -r; x < r; x+=2) {
      for (y = -r; y < r; y+=2) {
        let radius = dist(0, 0, x, y);
        if (radius <= r) {
          pg.beginDraw();
          pg.noStroke();
          /* 
           let is the fading of each particle in the clouds areas. let make the pink color, then minus a
           random number to add texture to the cloud, then minus y to make the bottom of the cloud darker 

           let made a list of other colours below.
           */
          if (pink) { 
            pg.fill(255-t, 100-t-x*3, 100-t-y*3, r-radius);
          } else if (blue) { 
            pg.fill(100-t+x*3, 100-t-y*3, 255-t-x, r-radius);
          } else if (orange) { 
            pg.fill(255-t-y*3, 100-t+x*3, 0, r-radius);
          } else if (grey) { 
            pg.fill(150-t-y*3, 150-t-y*3, 150-t-y*3, r-radius);
          }
          pg.ellipse(r+x, r+y, 4, 4);
          pg.endDraw();
        }
      }
    }
  }

  function drawCloudParticle() {
    /* let multipy by 2 */
    image(pg, loc.x, loc.y, r*2, -r*2);

    if (move)loc.add(vel);
    if (loc.x >= width) {
      loc.x = -r*2;
    }
  }
}

